(()=>{
const additions={
oi:['Допиши «До завтра!»: Até ___!',['amanha'],'Até amanhã! — до завтра.'],nome:['Напиши «Меня зовут Ана», начни с Meu nome…',['meu nome e ana'],'Meu nome é Ana.'],origem:['Вставь предлог с артиклем: Eu sou ___ Rússia.',['da'],'De + a = da: sou da Rússia.'],estar:['Вставь глагол: Eu ___ cansado. (Я устал.)',['estou'],'Для состояния: Eu estou cansado.'],artigos:['Добавь определённый артикль перед livro: ___ livro.',['o'],'O livro: слово livro мужского рода.'],nao:['Вставь «не»: Eu ___ falo português.',['nao'],'Não ставим перед глаголом.'],ter:['Вставь ter для «я»: Eu ___ uma irmã.',['tenho'],'Eu tenho uma irmã — у меня есть сестра.'],familia:['Вставь «моя», без артикля: ___ casa.',['minha'],'Casa женского рода: minha casa.'],rotina:['Поставь trabalhar: Você ___ todos os dias.',['trabalha'],'С você: trabalha.'],gostar:['Вставь предлог: Nós gostamos ___ música.',['de'],'Gostar de: gostamos de música.'],numeros:['Напиши число 5 по-португальски.',['cinco'],'5 — cinco.'],horas:['Допиши: São duas ___. (Сейчас два часа.)',['horas'],'São duas horas.'],cafe:['Допиши вежливую просьбу: Um café, por ___.',['favor'],'Por favor — пожалуйста в просьбе.'],compras:['Вставь «с помощью»: Posso pagar ___ cartão?',['com'],'Pagar com cartão — платить картой.'],onde:['Спроси «где»: ___ fica a farmácia?',['onde'],'Onde fica a farmácia?'],poder:['Поставь precisar для «я»: Eu ___ de ajuda.',['preciso'],'Eu preciso de ajuda — мне нужна помощь.'],saude:['Допиши: Estou ___ dor de cabeça.',['com'],'Estar com dor — испытывать боль.'],telefone:['Вставь repetir: Pode ___ a mensagem?',['repetir'],'После pode — repetir, начальная форма.'],amanha:['Поставь ir для nós: Nós ___ estudar amanhã.',['vamos'],'Nós vamos estudar amanhã.'],ontem:['Вставь ir в прошлом: Ontem eu ___ ao mercado.',['fui'],'Ontem eu fui ao mercado.'],passado:['Поставь comprar в прошлом: Ontem eu ___ pão.',['comprei'],'Eu comprei — я купил.'],imperfeito:['Поставь ser: Quando eu ___ criança… (Когда я был ребёнком…)',['era'],'Era описывает фон в прошлом.'],comparar:['Вставь связку сравнения: Este ônibus é mais caro ___ o táxi.',['que','do que'],'Mais caro que / do que — дороже, чем.'],condicional:['Вставь poder для вежливой просьбы: Você ___ repetir, por favor?',['poderia'],'Você poderia repetir? — Вы могли бы повторить?'],conectores:['Вставь «но»: Eu queria sair, ___ estava chovendo.',['mas'],'Mas связывает противопоставленные мысли.'],opiniao:['Вставь achar для eu: Eu ___ que o transporte é importante.',['acho'],'Eu acho que — я считаю, что.'],subjuntivo:['Поставь ter для возможного будущего: Quando eu ___ tempo, vou estudar.',['tiver'],'Quando eu tiver tempo — когда у меня будет время.'],email:['Напиши «С уважением» в конце письма одним словом.',['atenciosamente'],'Atenciosamente — нейтральное завершение делового письма.'],resumo:['Вставь voltar для o atendimento: O atendimento ___ amanhã.',['volta'],'O atendimento volta amanhã — обслуживание возобновится завтра.'],conversa:['Вставь repetir: Não entendi. Pode ___?',['repetir'],'Pode repetir? — можете повторить?']};
const norm=s=>String(s??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^\p{L}\p{N}\s]/gu,' ').replace(/\s+/g,' ').trim();
function bank(id){const foundation=window.BoraBeginner?.units[id];if(foundation)return foundation.tests.map((q,i)=>({...q,id:id+'-v2-'+i}));const lessons=window.BoraCourses[0].lessons,l=lessons.find(l=>l.id===id);if(!l)return [];const n=lessons.indexOf(l),all=lessons.flatMap(l=>l.examples);const choice=(q,correct,side,k)=>{const other=[...new Set(all.map(e=>e[side]).filter(t=>norm(t)!==norm(correct)))];const options=other.slice((n+k)%Math.max(1,other.length-3),(n+k)%Math.max(1,other.length-3)+3);const answer=(n+k)%4;options.splice(answer,0,correct);return {id:id+'-'+k,type:'choice',q,options,answer,why:correct}};const result=l.examples.slice(0,3).map((e,i)=>i===1?choice('Выбери фразу: «'+e[1]+'»',e[0],0,i):choice('Как перевести «'+e[0]+'»?',e[1],1,i));result.push({id:id+'-3',type:'short',q:l.write[0],answer:l.write[1],why:l.write[2]});const a=additions[id];result.push({id:id+'-4',type:'short',q:a[0],answer:a[1],why:a[2]});return result}
function grade(id,answers){const questions=bank(id),results=questions.map(q=>{const answer=String(answers?.[q.id]??'').slice(0,300),correct=answer!=='__unknown__'&&(q.type==='choice'?/^\d+$/.test(answer)&&Number(answer)===q.answer:q.answer.some(a=>norm(a)===norm(answer)));return {id:q.id,answer,correct}});const correct=results.filter(r=>r.correct).length;return {version:window.BoraBeginner?.units[id]?.version||1,correct,total:questions.length,percent:questions.length?Math.round(correct/questions.length*100):0,passed:questions.length>0&&correct/questions.length>=0.8,results}}
window.BoraLessonTests={version:1,bank,grade,norm};
})();
